/* SAS Basketball v0.1 | dependency-free front end with optional Supabase adapter. */
(() => {
  'use strict';
  const ROOT = document.getElementById('app');
  const config = window.SAS_CONFIG || {};
  const LIVE = Boolean(config.supabaseUrl && config.supabasePublishableKey);
  const DEMO_KEY = 'sas-basketball-demo-v1';
  const LOGO = 'public/assets/sas-eagle-red.png';
  const SCHOOL = 'public/assets/sas-horizontal-mark.png';
  const COMPETENCIES = ['Animal Press (2-2-1)','Man-to-Man Containment','Defensive Rebounding','Transition Offense','Transition Defense','Communication','Ball Pressure','Trapping & Rotations','Passing Accuracy','Decision-Making','Offensive Spacing','Attacking Closeouts','Finishing Through Contact','Shot Selection','DHO Defense','Ball Security','Pick-and-Roll Reads','Backdoor Prevention'];
  const NAV = { coach:[['dashboard','Home','⌂'],['practices','Practices','▣'],['drills','Drills','⬡'],['development','Development','◎'],['settings','More','•••']], player:[['dashboard','Home','⌂'],['goals','My Goals','◎'],['assignments','Assignments','☑'],['reflections','Reflect','✎'],['resources','Resources','▤']] };
  const today = () => {const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
  const dayOffset = n => {const d=new Date();d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
  const fullDate = x => {if(!x)return 'Date not set';return new Date(x+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})};
  const shortDate = x => {if(!x)return '—';return new Date(x+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})};
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const attr = esc;
  const id = () => typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : 'd-'+Math.random().toString(36).slice(2)+Date.now();
  const initials = n => (n || 'SAS').trim().split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
  const fmt = n => Math.round(Number(n)||0);
  let supabase = null;
  let toastTimer = null;
  const state = {role:null,profile:null,page:'dashboard',mode:LIVE?'live':'demo',authScreen:'entry',desiredRole:'player',loading:LIVE,loadError:'',busy:false,modal:null,draftActivities:[],editing:null,filter:'All',search:'',data:null};
  const demoSeed = () => {
    const players = [
      {id:'player-one',display_name:'Sample Player A',role:'player'},
      {id:'player-two',display_name:'Sample Player B',role:'player'}
    ];
    return {
      profiles:players,
      practices:[
        {id:'practice-one',practice_date:dayOffset(1),title:'Defensive Identity + Transition',location:'HS Gym',primary_priorities:['Animal Press (2-2-1)','Defensive Rebounding','Transition Offense'],peripheral_priorities:['Communication','Passing Accuracy'],activities:[{drill_id:'drill-one',name:'2v2 Advantage Recovery',completed:false},{drill_id:'drill-two',name:'4v4 Stop + Secure',completed:false}],live_application:'5v5: stops only count after a secured rebound. Live turnovers flow into transition.',layups_result:null,status:'planned',published:true},
        {id:'practice-two',practice_date:dayOffset(-2),title:'Decision-Making Under Pressure',location:'HS Gym',primary_priorities:['Ball Security','Offensive Spacing','Transition Defense'],peripheral_priorities:['Communication','Shot Selection'],activities:[{drill_id:'drill-three',name:'3v2 + 1 Continuous',completed:true},{drill_id:'drill-one',name:'2v2 Advantage Recovery',completed:true}],live_application:'5v5 transition with early decisions and defensive recovery.',layups_result:78,status:'completed',published:true},
        {id:'practice-three',practice_date:dayOffset(-5),title:'Pressure and Rebounding',location:'HS Gym',primary_priorities:['Animal Press (2-2-1)','Defensive Rebounding','Communication'],peripheral_priorities:['Ball Pressure','Transition Offense'],activities:[],live_application:'Full-court pressure into live 5v5.',layups_result:65,status:'completed',published:true}
      ],
      practice_notes:[{practice_id:'practice-two',notes:'Sample private coach observation. Players cannot access this section.',next_focus:'Improve transition communication.'}],
      drills:[
        {id:'drill-one',name:'2v2 Advantage Recovery',competency:'Man-to-Man Containment',situation:'Help and recovery after an offensive advantage',description:'Two defenders must communicate, contain penetration, and recover without conceding a direct finish.',coaching_cues:'Contain the ball. See both players. Communicate the rotation.',status:'Tested',published:true,created_by:'coach-demo'},
        {id:'drill-two',name:'4v4 Stop + Secure',competency:'Defensive Rebounding',situation:'Finishing a defensive possession',description:'Defenders earn a point only when a defensive stop ends with a controlled rebound.',coaching_cues:'Track flight. Locate opponent. Secure the ball with two hands.',status:'Proven',published:true,created_by:'coach-demo'},
        {id:'drill-three',name:'3v2 + 1 Continuous',competency:'Transition Offense',situation:'Numbers advantage before defense recovers',description:'Attack the temporary advantage and make early pass, drive, or shot decisions.',coaching_cues:'Wide lanes. Rim pressure. Make the next read quickly.',status:'Proven',published:true,created_by:'coach-demo'}
      ],
      assignments:[
        {id:'assignment-one',title:'Recognizing a Defensive Advantage',description:'Review our spacing principles. Write one read you can make when the defense overhelps.',due_date:dayOffset(3),published:true},
        {id:'assignment-two',title:'Rebounding Reflection',description:'Describe one way to track the ball and maintain contact with your matchup.',due_date:dayOffset(5),published:true}
      ],
      assignment_responses:[],
      goals:[{id:'goal-one',player_id:'player-one',title:'Finish stronger through contact',target:'Use a two-foot finish when appropriate in traffic.',status:'In progress',created_at:new Date().toISOString()}],
      reflections:[{id:'reflection-one',player_id:'player-one',prompt:'What did you recognize faster this week?',response:'I recognized when to get wide in transition.',created_at:new Date().toISOString()}]
    };
  };
  function loadDemo(){try{const d=JSON.parse(localStorage.getItem(DEMO_KEY)||'null');return d && d.practices && d.drills ? d : demoSeed()}catch{return demoSeed()}}
  function persistDemo(){if(!LIVE){try{localStorage.setItem(DEMO_KEY,JSON.stringify(state.data))}catch{/* Some sandbox/private browser contexts prohibit storage; this session remains usable. */}}}
  function userId(){return state.profile?.id || 'player-one'}
  function isCoach(){return state.role==='coach'}
  function records(t){return state.data?.[t] || []}
  function mine(t){return records(t).filter(x=>x.player_id===userId())}
  function visiblePractices(){return records('practices').filter(x=>isCoach() || x.published).sort((a,b)=>b.practice_date.localeCompare(a.practice_date))}
  function visibleDrills(){return records('drills').filter(x=>isCoach() || x.published)}
  function visibleAssignments(){return records('assignments').filter(x=>isCoach() || x.published)}
  function playerName(x){return records('profiles').find(p=>p.id===x)?.display_name || (x===userId()?state.profile?.display_name:'Player') || 'Player'}
  async function initialize(){
    if(!LIVE){state.loading=false;state.data=loadDemo();render();return}
    try{
      const mod=await import('https://esm.sh/@supabase/supabase-js@2');
      
supabase=mod.createClient(config.supabaseUrl,config.supabasePublishableKey,{db:{schema:'sas_basketball'}});

      const {data:{session},error}=await supabase.auth.getSession(); if(error)throw error;
      if(session)await loadUser(session.user.id); else{state.loading=false;render()}
      supabase.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.profile=null;state.role=null;state.authScreen='entry';state.loading=false;render()}});
    }catch(error){state.loading=false;state.loadError=error.message||String(error);render()}
  }
  async function loadUser(uid){
    state.loading=true;render();
    const {data:profile,error}=await supabase.from('profiles').select('id,display_name,role').eq('id',uid).single();
    if(error || !profile || !['coach','player'].includes(profile.role)){await supabase.auth.signOut();state.profile=null;state.role=null;state.loading=false;state.loadError='This account is not on the authorized team roster. Ask the administrator to provision it.';render();return}
    state.profile=profile;state.role=profile.role;state.page='dashboard';state.loadError='';await refreshLive();
  }
  async function refreshLive(){
    try{
      const tables=['profiles','practices','practice_notes','drills','assignments','assignment_responses','goals','reflections'];
      const loaded=await Promise.all(tables.map(table=>supabase.from(table).select('*')));
      loaded.forEach((r,i)=>{if(r.error)throw Error(tables[i]+': '+r.error.message)});
      state.data=Object.fromEntries(tables.map((t,i)=>[t,loaded[i].data||[]]));
      state.loading=false;render();
    }catch(error){state.loading=false;state.loadError='Cannot load team data: '+error.message;render()}
  }
  async function saveRow(table,row,kind='insert',match='id'){
    if(!LIVE){
      const arr=records(table);
      if(kind==='delete'){state.data[table]=arr.filter(x=>x[match]!==row[match]);persistDemo();return}
      if(kind==='update'){const found=arr.findIndex(x=>x[match]===row[match]);if(found>=0)arr[found]={...arr[found],...row};else arr.push({...row});persistDemo();return}
      arr.unshift({...row,id:row.id||id()});persistDemo();return
    }
    let q;
    if(kind==='update'){const {[match]:key,...values}=row;q=supabase.from(table).update(values).eq(match,key)}
    else if(kind==='delete')q=supabase.from(table).delete().eq(match,row[match]);
    else q=supabase.from(table).insert(row);
    const {error}=await q;if(error)throw error;
  }
  async function perform(fn,message='Saved successfully'){
    if(state.busy)return;
    try{state.busy=true;await fn();if(LIVE)await refreshLive();else render();notice(message)}
    catch(error){notice('Could not save: '+(error.message||error),true)}finally{state.busy=false}
  }
  function notice(message,err=false){const existing=document.querySelector('.toast');if(existing)existing.remove();const t=document.createElement('div');t.className='toast';t.textContent=message;if(err)t.style.background='#8f1b21';document.body.appendChild(t);if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),4500)}
  function openModal(type,obj=null){state.modal={type,obj};render()}
  function closeModal(){state.modal=null;render()}
  function go(page){state.modal=null;state.page=page;state.search='';state.filter='All';render();window.scrollTo({top:0,behavior:'instant'})}
  function title(text,desc='',action=''){return `<div class="pagehead"><div><div class="eyebrow">SAS PUXI · 2026–27 SEASON</div><h1>${esc(text)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>${action}</div>`}
  function pill(status){const variant=status==='Proven'||status==='Completed'||status==='completed'||status==='Done'?'greenpill':status==='In progress'||status==='Tested'?'redpill':'';return `<span class="pill ${variant}">${esc(status)}</span>`}
  function dateBox(d){const parts=(d||today()).split('-');let date=new Date((d||today())+'T12:00:00');return `<div class="datebox"><small>${date.toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small><big>${esc(Number(parts[2]))}</big></div>`}
  function navButton([page,label,icon]){return `<button class="side-button ${state.page===page?'active':''}" data-action="go" data-page="${page}"><span class="ico">${icon}</span><span>${label}</span></button>`}
  function mobileNavButton([page,label,icon]){return `<button class="${state.page===page?'active':''}" data-action="go" data-page="${page}"><span class="ico">${icon}</span><span>${label}</span></button>`}
  function shell(){const nav=NAV[state.role];const page=state.page;const labels={dashboard:isCoach()?'COACHES’ HUB':'PLAYERS’ HUB',practices:'PRACTICE PLANNER',drills:'DRILL LIBRARY',development:'PLAYER DEVELOPMENT',settings:'SETTINGS',goals:'MY GOALS',assignments:'ASSIGNMENTS',reflections:'REFLECTIONS',resources:'SKILL RESOURCES'};
    return `<div class="shell"><aside class="sidebar"><div class="side-brand"><img src="${LOGO}" alt="SAS eagle emblem"/><div><strong>SAS<br/>BASKETBALL</strong><small>PUXI EAGLES</small></div></div><div class="side-group">YOUR WORKSPACE</div>${nav.map(navButton).join('')}<div class="side-foot"><div class="profile-badge"><span class="avatar">${esc(initials(state.profile?.display_name))}</span><div class="profile-info"><strong>${esc(state.profile?.display_name)}</strong><small>${isCoach()?'Coaching Staff':'Varsity Player'}</small></div></div><button class="side-signout" data-action="signOut">${LIVE?'Sign out':'Return to demo entrance'}</button></div></aside><section class="main"><header class="topbar"><div class="mobilebar"><img src="${LOGO}" alt=""/><strong>SAS BASKETBALL</strong></div><span class="top-title">${esc(labels[page]||'SAS BASKETBALL')}</span><div class="top-right">${!LIVE?`<span class="pill redpill">DEMO DATA</span>`:''}<span class="role">${isCoach()?'Coach access':'Player access'}</span><img src="${LOGO}" alt="SAS eagle"/></div></header><main class="content">${mainContent()}</main></section><nav class="mobile-nav" aria-label="Main navigation">${nav.map(mobileNavButton).join('')}</nav></div>${state.modal?modal():''}`;
  }
  function entry(){return `<div class="entry"><div class="entry-inner"><section class="entry-brand"><img class="eagle" src="${LOGO}" alt="SAS eagle logo"/><div class="schoolname">SHANGHAI AMERICAN SCHOOL · PUXI</div><div class="massive">SAS <span>HOOPS.</span></div><p class="strap">PLAY HARD. PLAY SMART. PLAY TOGETHER.</p><p class="substrap">One team. One standard. One platform for everything we teach, practice, and develop.</p></section><section class="entry-panel">${!LIVE?`<div class="demo-ribbon" style="color:#9f2026;border-color:#e5b9bb;background:#fff2f2">INTERACTIVE PROTOTYPE · SAMPLE DATA</div>`:''}${state.authScreen==='login'?signInForm():`<div class="eyebrow">WELCOME TO THE PROGRAM</div><h2 class="panel-title" style="margin:8px 0 4px">Choose your workspace.</h2><p class="subtle">${LIVE?'Private accounts, role-based access.':'Explore either view with fictional sample records.'}</p><button class="entry-link" data-action="enter" data-role="player"><span class="entry-icon">♙</span><span class="spacer"><div class="entry-title">PLAYERS’ HUB</div><div class="entry-desc">My goals · Assignments · Reflections · Resources</div></span><span>→</span></button><button class="entry-link coach" data-action="enter" data-role="coach"><span class="entry-icon">▣</span><span class="spacer"><div class="entry-title">COACHES’ HUB</div><div class="entry-desc">Practice planning · Drills · Team development</div></span><span>→</span></button><div class="entry-footer">${LIVE?'Access is restricted to approved SAS Basketball accounts.':'Demo mode stores sample changes only in this browser. Do not enter real student information.'}</div>`}${state.loadError?`<div class="error" style="margin-top:13px">${esc(state.loadError)}</div>`:''}</section></div></div>`}
  function signInForm(){return `<button class="btn lightbtn slim" data-action="backEntry" style="margin-bottom:15px">← Back</button><div class="eyebrow">SECURE TEAM ACCESS</div><h2 class="panel-title" style="margin:9px 0 15px">Sign in</h2><form class="signin" data-form="signin"><div class="field"><label>Email address</label><input required type="email" name="email" autocomplete="username" placeholder="name@school.org"/></div><div class="field"><label>Password</label><input required type="password" name="password" autocomplete="current-password"/></div><button class="btn redbtn wide" type="submit">Sign in securely →</button><div class="info">The account's verified role determines which hub opens. Selecting Coaches' Hub never grants coach permissions.</div></form>`}
  function mainContent(){if(state.page==='practiceEditor')return practiceEditor(state.editing);if(isCoach())return ({dashboard:coachHome,practices:practicePage,drills:drillPage,development:coachDevelopment,settings:settingsPage}[state.page]||coachHome)();return ({dashboard:playerHome,goals:goalsPage,assignments:assignmentsPage,reflections:reflectionsPage,resources:resourcesPage}[state.page]||playerHome)()}
  function hero(coach){return `<div class="hero"><img class="hero-logo" src="${LOGO}" alt=""/><div class="eyebrow">${coach?'THE COACHES’ HUB':'THE PLAYERS’ HUB'} · 2026–27</div><h2>${coach?'BUILD THE STANDARD.':'OWN YOUR DEVELOPMENT.'}</h2><p>${coach?'Plan deliberately. Teach with purpose. Reflect on what transfers to live basketball.':'Understand the game. Recognize the situation. Make the next right decision.'}</p><button class="btn redbtn" data-action="go" data-page="${coach?'practices':'goals'}">${coach?'Open practice planner':'Review my goals'} →</button></div>`}
  function metric(label,num,tag=''){return `<div class="card stat"><small>${esc(label)}</small><b class="tabular">${esc(num)}</b>${tag?`<span class="tag">${esc(tag)}</span>`:''}</div>`}
  function practiceItem(p,buttonLabel='View'){return `<div class="list-card">${dateBox(p.practice_date)}<div class="body"><strong>${esc(p.title)}</strong><p>${esc(fullDate(p.practice_date))} · ${esc(p.location||'Gym')} · ${p.status==='completed'?'Completed':'Planned'}</p><div class="meta">${pill(p.status)}${p.published?`<span class="pill">Shared with players</span>`:''}</div></div><button class="btn ghost slim" data-action="${isCoach()?'editPractice':'practiceDetails'}" data-id="${attr(p.id)}">${esc(buttonLabel)} →</button></div>`}
  function benchmark(){const data=records('practices').filter(p=>p.status==='completed'&&p.layups_result!==null&&p.layups_result!==undefined).sort((a,b)=>a.practice_date.localeCompare(b.practice_date));const last=data.at(-1);return `<div class="card"><div class="row between"><div class="section-heading" style="margin:0">100 Layups Challenge</div><span class="pill redpill">10 MIN TARGET</span></div><div class="row" style="align-items:end;gap:15px;margin:16px 0"><div class="benchmark-number">${last?esc(last.layups_result):'—'}<span style="font-size:20px;color:#9298a0"> / 100</span></div><span class="muted small" style="padding-bottom:9px">Latest completed result</span></div><div class="progress"><div style="width:${last?Math.min(100,Math.max(0,Number(last.layups_result))):0}%"></div></div><div class="subtle" style="margin-top:11px">${data.length?`${data.length} completed challenge${data.length===1?'':'s'} recorded`:'No completed challenges yet'}</div>${data.slice(-4).reverse().map(x=>`<div class="barrow"><span>${esc(shortDate(x.practice_date))}</span><div class="progress"><div style="width:${Math.min(100,Math.max(0,Number(x.layups_result)))}%"></div></div><span>${esc(x.layups_result)}</span></div>`).join('')}</div>`}
  function coachHome(){const practices=records('practices');const completed=practices.filter(x=>x.status==='completed');const upcoming=practices.filter(x=>x.practice_date>=today()).sort((a,b)=>a.practice_date.localeCompare(b.practice_date));const priorities={};completed.forEach(p=>p.primary_priorities?.forEach(x=>{priorities[x]=(priorities[x]||0)+1}));const most=Object.entries(priorities).sort((a,b)=>b[1]-a[1]).slice(0,3);
    return `<div class="stack">${title('Coaches’ Hub','The home base for purposeful, collaborative coaching.',`<button class="btn redbtn" data-action="newPractice">+ New practice</button>`)}${hero(true)}<div class="grid4 stat-grid">${metric('Completed practices',completed.length)}${metric('Planned sessions',practices.filter(x=>x.status==='planned').length)}${metric('Library drills',records('drills').length)}${metric('Players with goals',new Set(records('goals').map(g=>g.player_id)).size)}</div><div class="grid2"><div class="card"><div class="row between"><div class="section-heading">Upcoming practices</div><button class="btn lightbtn slim" data-action="go" data-page="practices">See all</button></div>${upcoming.length?upcoming.slice(0,3).map(p=>practiceItem(p,'Plan')).join(''):`<div class="empty">No upcoming practices planned.<br/>Create the next session.</div>`}</div>${benchmark()}</div><div class="grid2"><div class="card"><div class="section-heading">Primary Priority Frequency</div><p class="subtle">Counts completed practices where the competency was a Primary Priority, not minutes spent.</p>${most.length?most.map(([name,n])=>`<div class="barrow" style="grid-template-columns:150px 1fr 30px"><span>${esc(name)}</span><div class="progress"><div style="width:${n/Math.max(...most.map(x=>x[1]))*100}%"></div></div><span>${n}</span></div>`).join(''):`<div class="empty">Complete practices to begin tracking priorities.</div>`}</div><div class="card"><div class="section-heading">Quick actions</div><div class="responsive-stack"><button class="action-card" data-action="newPractice"><span class="icon-square">▣</span><span><b>Create a practice</b><small>Set priorities and game-based activities</small></span></button><button class="action-card" data-action="newDrill"><span class="icon-square">⬡</span><span><b>Add to Drill Library</b><small>Share a competitive teaching activity</small></span></button><button class="action-card" data-action="go" data-page="development"><span class="icon-square">◎</span><span><b>Review player development</b><small>Goals, reflections, and assignments</small></span></button></div></div></div></div>`}
  function playerHome(){const published=visiblePractices().filter(x=>x.practice_date>=today()).sort((a,b)=>a.practice_date.localeCompare(b.practice_date));const assignments=visibleAssignments();const completed=records('assignment_responses').filter(r=>r.player_id===userId());const open=assignments.filter(a=>!completed.some(x=>x.assignment_id===a.id));const goals=mine('goals');const name=(state.profile?.display_name||'Player').split(' ')[0];
    return `<div class="stack">${title('My Basketball Hub',`Welcome, ${name}. Your development starts with your decisions.`)}${hero(false)}<div class="grid4 stat-grid">${metric('My active goals',goals.filter(g=>g.status!=='Completed').length)}${metric('Assignments due',open.length)}${metric('My reflections',mine('reflections').length)}${metric('Team practices',visiblePractices().length)}</div><div class="grid2"><div class="card"><div class="row between"><div class="section-heading">Up next</div><span class="pill redpill">TEAM PRACTICE</span></div>${published.length?practiceItem(published[0],'View'):`<div class="empty">No upcoming practice has been published.</div>`}${published[0]?`<div class="divider"></div><div class="section-label" style="margin-bottom:9px">PRACTICE FOCUS</div>${published[0].primary_priorities?.map((p,i)=>`<div class="priority" style="margin-top:6px"><i>${i+1}.</i>${esc(p)}</div>`).join('')}`:''}</div><div class="card"><div class="row between"><div class="section-heading">My next steps</div><button class="btn lightbtn slim" data-action="go" data-page="assignments">View all</button></div>${open.length?open.slice(0,3).map(a=>`<div class="list-card"><span class="icon-square" style="width:38px;height:38px;flex-basis:38px">☑</span><div class="body"><strong>${esc(a.title)}</strong><p>Due ${esc(fullDate(a.due_date))}</p></div><button class="btn ghost slim" data-action="respondAssignment" data-id="${attr(a.id)}">Open</button></div>`).join(''):`<div class="empty">All current assignments are complete.</div>`}<div class="divider"></div><button class="action-card" data-action="newReflection"><span class="icon-square">✎</span><span><b>Reflection check-in</b><small>What did you recognize and improve?</small></span></button></div></div><div class="grid2"><div class="card"><div class="section-heading">My goals</div>${goals.length?goals.slice(0,3).map(g=>`<div class="note-row"><div class="row between"><b style="font-size:12px">${esc(g.title)}</b>${pill(g.status)}</div><p class="subtle" style="margin-top:5px">${esc(g.target||'')}</p></div>`).join(''):`<div class="empty">No personal goals yet.</div>`}<button class="btn ghost slim" data-action="go" data-page="goals" style="margin-top:15px">See development goals →</button></div><div class="card"><div class="section-heading">Our identity</div><div class="notices"><b>PLAY HARD.</b> Compete every possession.<br/><b>PLAY SMART.</b> See the advantage and make the right read.<br/><b>PLAY TOGETHER.</b> Communicate and stay connected.</div><img class="logo-stamp" style="margin-top:24px" src="${SCHOOL}" alt="Shanghai American School"/></div></div></div>`}
  function practiceManagementRow(p){return `<div class="list-card">${dateBox(p.practice_date)}<div class="body"><strong>${esc(p.title)}</strong><p>${esc(fullDate(p.practice_date))} · ${esc(p.location||'HS Gym')}</p><div class="meta">${pill(p.status)}${p.published?'<span class="pill">Player-visible</span>':''}</div></div><div class="column" style="gap:6px"><button class="btn ghost slim" data-action="editPractice" data-id="${attr(p.id)}">Edit</button><button class="btn redbtn slim" data-action="logPractice" data-id="${attr(p.id)}">Check-in</button></div></div>`}
  function practicePage(){const ps=visiblePractices();return `<div class="stack">${title('Practice Planner','Primary Priorities. Peripheral Priorities. Competitive application.',`<button class="btn redbtn" data-action="newPractice">+ New practice</button>`)}<div class="notices"><b>Coaching standard:</b> Teach the read, reproduce the situation, compete, then evaluate the transfer. Practice sequences stay flexible; no forced drill timestamps.</div><div class="grid2"><div class="card"><div class="section-heading">Practice schedule & archive</div>${ps.length?ps.map(p=>practiceManagementRow(p)).join(''):`<div class="empty">Your first practice will appear here.</div>`}</div>${benchmark()}</div></div>`}
  function prioritySelect(name,value=''){return `<select name="${name}" required><option value="">Select competency...</option>${COMPETENCIES.map(x=>`<option value="${attr(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`}
  function practiceEditor(p){const editing=Boolean(p);const primary=p?.primary_priorities||[];const peripheral=p?.peripheral_priorities||[];const activities=state.draftActivities;return `<div class="stack">${title(editing?'Edit Practice':'Create Practice','A clear plan for teaching and transfer.',`<button class="btn ghost" data-action="go" data-page="practices">← Back to practices</button>`)}<form id="practice-form" data-form="practice" class="stack form-panel"><div class="card"><div class="section-heading">01 · Session details</div><div class="form-grid"><div class="field"><label>Date</label><input type="date" name="practice_date" required value="${attr(p?.practice_date||today())}"/></div><div class="field"><label>Location</label><input name="location" value="${attr(p?.location||'HS Gym')}" placeholder="Gym or court"/></div></div><div class="field" style="margin-top:13px"><label>Practice title</label><input name="title" required maxlength="100" value="${attr(p?.title||'')}" placeholder="e.g., Press into Transition"/></div></div><div class="card"><div class="section-heading">02 · Instructional priorities</div><div class="section-label" style="margin:8px 0">THREE PRIMARY PRIORITIES</div><div class="form-grid">${[0,1,2].map(i=>`<div class="field"><label>Primary ${i+1}</label>${prioritySelect('primary_'+i,primary[i])}</div>`).join('')}</div><div class="section-label" style="margin:20px 0 8px">TWO PERIPHERAL PRIORITIES</div><div class="form-grid">${[0,1].map(i=>`<div class="field"><label>Peripheral ${i+1}</label>${prioritySelect('peripheral_'+i,peripheral[i])}</div>`).join('')}</div></div><div class="card"><div class="row between"><div class="section-heading">03 · Activity sequence</div><button class="btn ghost slim" type="button" data-action="addActivity">+ Add drill</button></div><div class="notices" style="margin-bottom:14px"><b>Default opening benchmark:</b> 100 Layups Challenge, 10 minutes. Record actual makes after practice. This remains separate from instructional priorities.</div><div class="activity"><span class="index">★</span><span class="name">100 Layups Challenge <span class="pill redpill">BENCHMARK</span></span></div>${activities.map((x,i)=>`<div class="activity"><span class="index">${i+1}</span><span class="name">${esc(x.name)}</span><button type="button" class="micro" data-action="moveActivity" data-index="${i}" data-dir="-1" aria-label="Move up">↑</button><button type="button" class="micro" data-action="moveActivity" data-index="${i}" data-dir="1" aria-label="Move down">↓</button><button type="button" class="micro" data-action="removeActivity" data-index="${i}" aria-label="Remove drill">×</button></div>`).join('')}<p class="subtle" style="margin-top:13px">Optional activities can be reordered at any time. No rigid time blocks required.</p></div><div class="card"><div class="section-heading">04 · Competitive application</div><div class="field"><label>How will today's priorities transfer to live basketball?</label><textarea name="live_application" placeholder="e.g., 5v5 stops only count after a secured rebound">${esc(p?.live_application||'')}</textarea></div><label class="check-label" style="margin-top:15px"><input type="checkbox" name="published" ${p?.published?'checked':''}/> Share this plan with players</label><p class="subtle" style="margin-top:7px">Coach-only reflections remain in a completely separate private record.</p></div><div class="row wrap"><button class="btn redbtn" type="submit">${editing?'Save changes':'Create practice'} →</button><button class="btn ghost" type="button" data-action="go" data-page="practices">Cancel</button></div></form></div>`}
  function drillPage(){const drills=visibleDrills().filter(d=>(state.filter==='All'||d.status===state.filter)&&[d.name,d.competency,d.description].join(' ').toLowerCase().includes(state.search.toLowerCase()));return `<div class="stack">${title('Shared Drill Library','Build a bank of competitive, transferable teaching activities.',`<button class="btn redbtn" data-action="newDrill">+ New drill</button>`)}<div class="controlbar"><input class="search" id="drill-search" placeholder="Search drills and competencies..." value="${attr(state.search)}" aria-label="Search drills"/><div class="filterrow">${['All','Proposed','Tested','Proven'].map(f=>`<button class="filterbtn ${state.filter===f?'selected':''}" data-action="filter" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="grid3">${drills.length?drills.map(d=>`<div class="card drill-card"><div><div class="drill-top">${pill(d.status)}${d.published?`<span class="pill">Player resource</span>`:''}</div><h3 style="margin:12px 0 8px">${esc(d.name)}</h3><span class="tagline">${esc(d.competency)}</span><p style="margin-top:10px">${esc(d.description)}</p></div><footer><span class="subtle">${esc(d.situation||'Competitive teaching activity')}</span><button class="btn ghost slim" data-action="drillDetails" data-id="${attr(d.id)}">View →</button></footer></div>`).join(''):`<div class="empty">No drills match the current search.</div>`}</div></div>`}
  function coachDevelopment(){const players=records('profiles').filter(p=>p.role==='player');return `<div class="stack">${title('Player Development','Track individual goals, reflections, and learning assignments.',`<button class="btn redbtn" data-action="newAssignment">+ New assignment</button>`)}<div class="grid2"><div class="card"><div class="row between"><div class="section-heading">Learning assignments</div><span class="pill">${records('assignments').length} total</span></div>${records('assignments').map(a=>{const submissions=records('assignment_responses').filter(r=>r.assignment_id===a.id).length;return `<div class="note-row"><div class="row between"><strong style="font-size:12px">${esc(a.title)}</strong>${pill(a.published?'Published':'Draft')}</div><div class="subtle">Due ${esc(fullDate(a.due_date))} · ${submissions} response${submissions===1?'':'s'}</div></div>`}).join('')||`<div class="empty">Create the first learning assignment.</div>`}</div><div class="card"><div class="section-heading">Player overview</div>${players.map(p=>`<div class="list-card"><div class="avatar-sm">${esc(initials(p.display_name))}</div><div class="body"><strong>${esc(p.display_name)}</strong><p>${records('goals').filter(x=>x.player_id===p.id).length} goals · ${records('reflections').filter(x=>x.player_id===p.id).length} reflections</p></div><button class="btn ghost slim" data-action="playerDetails" data-id="${attr(p.id)}">Review</button></div>`).join('')||`<div class="empty">No player accounts are provisioned yet.</div>`}</div></div><div class="card"><div class="section-heading">Recent reflections & submissions</div>${records('reflections').slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,5).map(r=>`<div class="note-row"><b style="font-size:12px">${esc(playerName(r.player_id))}</b><p class="subtle">${esc(r.prompt)}</p><p style="font-size:12px;line-height:1.65;margin-top:4px">${esc(r.response)}</p></div>`).join('')||`<div class="empty">No player reflections submitted.</div>`}${records('assignment_responses').map(r=>`<div class="note-row"><b style="font-size:12px">${esc(playerName(r.player_id))} · ${esc(records('assignments').find(a=>a.id===r.assignment_id)?.title)}</b><p style="font-size:12px;line-height:1.65;margin-top:4px">${esc(r.response)}</p></div>`).join('')}</div></div>`}
  function goalsPage(){const goals=mine('goals');return `<div class="stack">${title('My Goals','Make development measurable and intentional.',`<button class="btn redbtn" data-action="newGoal">+ Add goal</button>`)}<div class="notices">A useful goal names a basketball decision or execution skill, identifies when it matters, and explains what progress looks like.</div><div class="grid2">${goals.map(g=>`<div class="card"><div class="row between"><span class="eyebrow">DEVELOPMENT TARGET</span>${pill(g.status)}</div><h3 style="margin:13px 0">${esc(g.title)}</h3><p class="subtle">${esc(g.target)}</p><div class="divider"></div><label class="field"><label>Update progress</label><select data-change="goalStatus" data-id="${attr(g.id)}"><option ${g.status==='Not started'?'selected':''}>Not started</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option ${g.status==='Completed'?'selected':''}>Completed</option></select></label></div>`).join('')||`<div class="empty">You haven't set a goal yet. Add one to begin tracking progress.</div>`}</div></div>`}
  function assignmentsPage(){const completed=mine('assignment_responses');return `<div class="stack">${title('Assignments','Learn the concept. Make the read. Apply it in live play.')}<div class="grid2">${visibleAssignments().map(a=>{const response=completed.find(r=>r.assignment_id===a.id);return `<div class="card"><div class="row between"><span class="eyebrow">PLAYER DEVELOPMENT</span>${pill(response?'Completed':'To do')}</div><h3 style="margin:12px 0">${esc(a.title)}</h3><p class="subtle" style="min-height:48px">${esc(a.description)}</p><div class="divider"></div><div class="row between"><span class="small muted">Due ${esc(fullDate(a.due_date))}</span><button class="btn ${response?'ghost':'redbtn'} slim" data-action="respondAssignment" data-id="${attr(a.id)}">${response?'Review response':'Open assignment'} →</button></div></div>`}).join('')||`<div class="empty">No published assignments currently.</div>`}</div></div>`}
  function reflectionsPage(){return `<div class="stack">${title('My Reflections','Recognize your decisions, then identify your next improvement.',`<button class="btn redbtn" data-action="newReflection">+ New reflection</button>`)}<div class="grid2"><div class="card"><div class="section-heading">Reflection prompts</div><div class="notices"><b>Recognition:</b> What did you notice more quickly?<br/><b>Decision:</b> What choice did you make?<br/><b>Transfer:</b> What will you do in the next live situation?</div><button class="btn darkbtn" data-action="newReflection" style="margin-top:16px">Write a reflection →</button></div><div class="card"><div class="section-heading">My reflection log</div>${mine('reflections').slice().reverse().map(r=>`<div class="note-row"><b style="font-size:12px">${esc(r.prompt)}</b><p class="subtle">${esc(shortDate(String(r.created_at).slice(0,10)))}</p><p style="font-size:12px;line-height:1.65;margin-top:5px">${esc(r.response)}</p></div>`).join('')||`<div class="empty">Your reflections will appear here.</div>`}</div></div></div>`}
  function resourcesPage(){return `<div class="stack">${title('Skill Resources','Coach-approved drills and team concepts.')}<div class="notices">Only drills deliberately shared by coaches appear here. Private coaching evaluations and scouting notes never appear in this view.</div><div class="grid3">${visibleDrills().map(d=>`<div class="card drill-card"><div><span class="tagline">${esc(d.competency)}</span><h3 style="margin:12px 0">${esc(d.name)}</h3><p>${esc(d.description)}</p></div><button class="btn ghost slim" data-action="drillDetails" data-id="${attr(d.id)}">Study the drill →</button></div>`).join('')||`<div class="empty">No coach-approved resources available yet.</div>`}</div></div>`}
  function settingsPage(){return `<div class="stack">${title('Program Settings','Season information and access configuration.')}<div class="grid2"><div class="card"><div class="section-heading">Program identity</div><div class="row start"><img src="${LOGO}" style="width:95px;height:95px;object-fit:contain" alt="SAS eagle"/><div><h3>SAS Puxi Girls Varsity</h3><p class="subtle">Season 2026–27</p><p class="subtle" style="margin-top:13px">Play hard. Play smart. Play together.</p></div></div></div><div class="card"><div class="section-heading">Account access</div><p class="subtle">${LIVE?'Signed in with Supabase Auth. Authorization is enforced by database-level Row Level Security.':'This is demo mode. Hub switching is for preview only and does not protect information. Do not use demo mode with real student records.'}</p><button class="btn ghost" style="margin-top:16px" data-action="signOut">${LIVE?'Sign out':'Exit demo'}</button>${!LIVE?`<button class="btn lightbtn" style="margin:16px 0 0 8px" data-action="resetDemo">Reset sample data</button>`:''}</div></div></div>`}
  function drillOptions(selected){return visibleDrills().map(d=>`<option value="${attr(d.id)}" ${d.id===selected?'selected':''}>${esc(d.name)}</option>`).join('')}
  function modal(){const {type,obj}=state.modal;let heading='',body='',footer='';
    if(type==='newDrill'){heading='Add a Drill';body=`<form id="modal-form" data-form="drill" class="stack"><div class="field"><label>Drill name</label><input name="name" required maxlength="90"/></div><div class="field"><label>Primary competency</label>${prioritySelect('competency')}</div><div class="field"><label>Basketball situation</label><input name="situation" placeholder="What game situation does it reproduce?" required/></div><div class="field"><label>Execution instructions</label><textarea name="description" required></textarea></div><div class="field"><label>Coaching cues</label><textarea name="coaching_cues" placeholder="What should players recognize and decide?"></textarea></div><div class="form-grid"><div class="field"><label>Evidence status</label><select name="status"><option>Proposed</option><option>Tested</option><option>Proven</option></select></div><div class="field"><label>Player visibility</label><select name="published"><option value="false">Coaches only</option><option value="true">Publish to players</option></select></div></div></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Save drill</button>`}
    else if(type==='drillDetails'){const d=obj;heading=d.name;body=`<div class="stack"><div class="row">${pill(d.status)}<span class="tagline">${esc(d.competency)}</span></div><div><div class="section-label">GAME SITUATION</div><p class="subtle" style="margin-top:6px">${esc(d.situation)}</p></div><div><div class="section-label">HOW IT WORKS</div><p style="font-size:13px;line-height:1.7;margin-top:6px">${esc(d.description)}</p></div><div><div class="section-label">COACHING CUES</div><p style="font-size:13px;line-height:1.7;margin-top:6px">${esc(d.coaching_cues||'No additional cues recorded.')}</p></div></div>`}
    else if(type==='addActivity'){heading='Add a drill to practice';body=`<form id="modal-form" data-form="addActivity" class="stack"><div class="field"><label>Choose drill</label><select name="drill_id" required>${drillOptions('')}</select></div><p class="subtle">Drills can be reordered after adding them.</p></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Add activity</button>`}
    else if(type==='practiceDetails'){const p=obj;heading=p.title;body=`<div class="stack"><span class="eyebrow">${esc(fullDate(p.practice_date))} · ${esc(p.location||'Gym')}</span><div class="section-label">THREE PRIMARY PRIORITIES</div>${p.primary_priorities.map(x=>`<div class="priority"><i>●</i>${esc(x)}</div>`).join('')}<div class="section-label">TWO PERIPHERAL PRIORITIES</div>${p.peripheral_priorities.map(x=>`<div class="priority"><i>○</i>${esc(x)}</div>`).join('')}<div class="section-label">COMPETITIVE APPLICATION</div><p class="subtle">${esc(p.live_application||'To be announced')}</p><div class="section-label">PRACTICE ACTIVITIES</div>${p.activities?.map(x=>`<div class="priority">${esc(x.name)}</div>`).join('')||'<p class="subtle">No additional activities published.</p>'}${p.layups_result!==null?`<span class="tagline">100 Layups: ${esc(p.layups_result)}/100</span>`:''}</div>`}
    else if(type==='logPractice'){const p=obj;const n=records('practice_notes').find(x=>x.practice_id===p.id);heading='Post-Practice Check-In';body=`<form id="modal-form" data-form="logPractice" class="stack"><div class="notices"><b>${esc(p.title)}</b><br/>Record what actually happened, not what was planned.</div><div class="form-grid"><div class="field"><label>100 Layups successful makes (10 min)</label><input name="layups_result" type="number" min="0" max="100" required value="${attr(p.layups_result??'')}"/></div><div class="field"><label>Practice status</label><select name="status"><option value="completed" ${p.status==='completed'?'selected':''}>Completed</option><option value="planned" ${p.status==='planned'?'selected':''}>Planned</option></select></div></div><div class="section-label">ACTIVITIES ACTUALLY COMPLETED</div>${(p.activities||[]).length?p.activities.map((a,i)=>`<label class="choice"><input type="checkbox" name="activity_${i}" ${a.completed?'checked':''}/> ${esc(a.name)}</label>`).join(''):`<p class="subtle">No additional drills listed.</p>`}<div class="field"><label>Private coach reflection (NOT player-visible)</label><textarea name="notes" placeholder="What worked? What needs improvement?">${esc(n?.notes||'')}</textarea></div><div class="field"><label>Next practice emphasis</label><input name="next_focus" value="${attr(n?.next_focus||'')}" placeholder="What will we reinforce next?"/></div></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Save check-in</button>`}
    else if(type==='newAssignment'){heading='Create Learning Assignment';body=`<form id="modal-form" data-form="assignment" class="stack"><div class="field"><label>Assignment title</label><input name="title" required/></div><div class="field"><label>Instructions / basketball learning target</label><textarea name="description" required></textarea></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="${dayOffset(7)}" required/></div><label class="check-label"><input type="checkbox" name="published" checked/> Publish to players</label></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Create assignment</button>`}
    else if(type==='respondAssignment'){const a=obj;const existing=mine('assignment_responses').find(r=>r.assignment_id===a.id);heading=a.title;body=`<form id="modal-form" data-form="response" class="stack"><div class="notices">${esc(a.description)}</div><div class="field"><label>My response</label><textarea name="response" required minlength="8" placeholder="Describe your read, decision, and application...">${esc(existing?.response||'')}</textarea></div><p class="subtle">Due ${esc(fullDate(a.due_date))}. Your submission is private to you and coaches.</p></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">${existing?'Update response':'Submit response'}</button>`}
    else if(type==='newGoal'){heading='Set a Development Goal';body=`<form id="modal-form" data-form="goal" class="stack"><div class="field"><label>Development goal</label><input name="title" required placeholder="e.g., Recognize driving angles"/></div><div class="field"><label>What will progress look like in a game?</label><textarea name="target" required placeholder="Name an observable action or decision."></textarea></div></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Save goal</button>`}
    else if(type==='newReflection'){heading='Player Reflection';body=`<form id="modal-form" data-form="reflection" class="stack"><div class="field"><label>Reflection prompt</label><select name="prompt"><option>What did you recognize faster this week?</option><option>What basketball decision do you want to improve?</option><option>When did you help the team communicate better?</option><option>What did you learn from a challenging possession?</option></select></div><div class="field"><label>My reflection</label><textarea name="response" minlength="8" required placeholder="Explain the situation, your decision, and what you will try next."></textarea></div></form>`;footer=`<button class="btn redbtn" type="submit" form="modal-form">Submit reflection</button>`}
    else if(type==='playerDetails'){const p=obj;heading=p.display_name;const goals=records('goals').filter(x=>x.player_id===p.id);const reflections=records('reflections').filter(x=>x.player_id===p.id);const submissions=records('assignment_responses').filter(x=>x.player_id===p.id);body=`<div class="stack"><div class="section-label">GOALS</div>${goals.map(g=>`<div class="note-row"><div class="row between"><b>${esc(g.title)}</b>${pill(g.status)}</div><p class="subtle">${esc(g.target)}</p></div>`).join('')||'<p class="subtle">No goals on record.</p>'}<div class="section-label">REFLECTIONS</div>${reflections.map(r=>`<div class="note-row"><b class="small">${esc(r.prompt)}</b><p class="subtle">${esc(r.response)}</p></div>`).join('')||'<p class="subtle">No reflections on record.</p>'}<div class="section-label">ASSIGNMENT RESPONSES</div>${submissions.map(r=>`<div class="note-row"><b class="small">${esc(records('assignments').find(a=>a.id===r.assignment_id)?.title||'Assignment')}</b><p class="subtle">${esc(r.response)}</p></div>`).join('')||'<p class="subtle">No responses on record.</p>'}</div>`}
    return `<div class="overlay" data-action="closeBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${attr(heading)}"><div class="modal-header"><h2>${esc(heading)}</h2><button class="btn iconbtn lightbtn" data-action="closeModal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button class="btn ghost" data-action="closeModal">Close</button>${footer}</div></section></div>`;
  }
  function render(){ROOT.innerHTML=state.loading?'<div class="loading">SAS BASKETBALL</div>':state.role?shell():entry()}
  function demoEnter(role){state.role=role;state.profile=role==='coach'?{id:'coach-demo',display_name:'Coach Demo',role:'coach'}:records('profiles').find(p=>p.id==='player-one');state.page='dashboard';state.authScreen='entry';render()}
  function startPractice(p){state.editing=p||null;state.draftActivities=(p?.activities||[]).map(a=>({...a}));state.page='practiceEditor';state.modal=null;render();window.scrollTo(0,0)}
  document.addEventListener('click',async event=>{
    const el=event.target.closest('[data-action]');if(!el || !ROOT.contains(el))return;
    const action=el.dataset.action;
    if(action==='closeBackdrop' && event.target!==el)return;
    if(action==='go'){go(el.dataset.page);return}
    if(action==='enter'){state.desiredRole=el.dataset.role;if(LIVE){state.authScreen='login';render()}else demoEnter(el.dataset.role);return}
    if(action==='backEntry'){state.authScreen='entry';state.loadError='';render();return}
    if(action==='signOut'){if(LIVE&&supabase)await supabase.auth.signOut();state.role=null;state.profile=null;state.page='dashboard';state.authScreen='entry';render();return}
    if(action==='resetDemo'){if(!LIVE){try{localStorage.removeItem(DEMO_KEY)}catch{}state.data=demoSeed();render();notice('Sample data reset')}return}
    if(action==='newPractice'){startPractice(null);return}
    if(action==='editPractice'){startPractice(records('practices').find(x=>x.id===el.dataset.id));return}
    if(action==='newDrill'){openModal('newDrill');return}
    if(action==='newAssignment'){openModal('newAssignment');return}
    if(action==='newGoal'){openModal('newGoal');return}
    if(action==='newReflection'){openModal('newReflection');return}
    if(action==='filter'){state.filter=el.dataset.filter;render();return}
    if(action==='closeModal'||action==='closeBackdrop'){closeModal();return}
    if(action==='addActivity'){if(!records('drills').length){notice('Add a drill to your library first',true);return}openModal('addActivity');return}
    if(action==='moveActivity'){const i=Number(el.dataset.index);const j=i+Number(el.dataset.dir);if(j>=0&&j<state.draftActivities.length){[state.draftActivities[i],state.draftActivities[j]]=[state.draftActivities[j],state.draftActivities[i]];render()}return}
    if(action==='removeActivity'){state.draftActivities.splice(Number(el.dataset.index),1);render();return}
    if(action==='logPractice'){openModal('logPractice',records('practices').find(x=>x.id===el.dataset.id));return}
    if(['drillDetails','practiceDetails','respondAssignment','playerDetails'].includes(action)){
      const table={drillDetails:'drills',practiceDetails:'practices',respondAssignment:'assignments',playerDetails:'profiles'}[action];const object=records(table).find(x=>x.id===el.dataset.id);
      if(object)openModal(action,object);return;
    }
  });
  document.addEventListener('input',event=>{if(event.target.id==='drill-search'){const s=event.target.value;state.search=s;const focus=event.target.selectionStart;render();const next=document.querySelector('#drill-search');if(next){next.focus();next.setSelectionRange(focus,focus)}}});
  document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.change==='goalStatus'&&state.role==='player'){const existing=mine('goals').find(g=>g.id===el.dataset.id);if(existing)await perform(()=>saveRow('goals',{id:existing.id,status:el.value},'update'),'Goal progress updated')}});
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();
    const f=Object.fromEntries(new FormData(form).entries());const type=form.dataset.form;
    if(type==='signin'){
      state.loadError='';try{state.busy=true;const {data,error}=await supabase.auth.signInWithPassword({email:f.email,password:f.password});if(error)throw error;await loadUser(data.user.id)}catch(e){state.loadError=e.message;render()}finally{state.busy=false}return;
    }
    if(type==='practice'&&isCoach()){
      const pri=[f.primary_0,f.primary_1,f.primary_2],per=[f.peripheral_0,f.peripheral_1];
      if(new Set([...pri,...per]).size!==5){notice('Select five distinct priorities so each has a clear purpose.',true);return}
      const practice={practice_date:f.practice_date,title:f.title.trim(),location:f.location.trim(),primary_priorities:pri,peripheral_priorities:per,activities:state.draftActivities,live_application:f.live_application,published:Boolean(f.published),status:state.editing?.status||'planned',layups_result:state.editing?.layups_result??null};
      const old=state.editing;
      await perform(async()=>{if(old)await saveRow('practices',{...practice,id:old.id},'update');else await saveRow('practices',practice);state.editing=null;state.page='practices'},old?'Practice updated':'Practice created');return;
    }
    if(type==='drill'&&isCoach()){await perform(async()=>{await saveRow('drills',{name:f.name,competency:f.competency,situation:f.situation,description:f.description,coaching_cues:f.coaching_cues,status:f.status,published:f.published==='true',created_by:userId()});state.modal=null},'Drill saved to library');return}
    if(type==='addActivity'&&isCoach()){const d=records('drills').find(x=>x.id===f.drill_id);if(d){state.draftActivities.push({drill_id:d.id,name:d.name,completed:false});closeModal()}return}
    if(type==='logPractice'&&isCoach()){
      const p=state.modal.obj;const note=records('practice_notes').find(x=>x.practice_id===p.id);
      const activities=(p.activities||[]).map((a,i)=>({...a,completed:Boolean(f['activity_'+i])}));
      await perform(async()=>{
        await saveRow('practices',{id:p.id,layups_result:Number(f.layups_result),status:f.status,activities},'update');
        const record={practice_id:p.id,notes:f.notes||'',next_focus:f.next_focus||''};
        if(note)await saveRow('practice_notes',record,'update','practice_id');else await saveRow('practice_notes',record);
        state.modal=null;
      },'Practice check-in recorded');return;
    }
    if(type==='assignment'&&isCoach()){await perform(async()=>{await saveRow('assignments',{title:f.title,description:f.description,due_date:f.due_date,published:Boolean(f.published)});state.modal=null},'Assignment created');return}
    if(type==='response'&&!isCoach()){const a=state.modal.obj;const old=mine('assignment_responses').find(r=>r.assignment_id===a.id);await perform(async()=>{if(old)await saveRow('assignment_responses',{id:old.id,response:f.response},'update');else await saveRow('assignment_responses',{assignment_id:a.id,player_id:userId(),response:f.response});state.modal=null},'Assignment response saved');return}
    if(type==='goal'&&!isCoach()){await perform(async()=>{await saveRow('goals',{player_id:userId(),title:f.title,target:f.target,status:'Not started',created_at:new Date().toISOString()});state.modal=null},'Goal added');return}
    if(type==='reflection'&&!isCoach()){await perform(async()=>{await saveRow('reflections',{player_id:userId(),prompt:f.prompt,response:f.response,created_at:new Date().toISOString()});state.modal=null},'Reflection saved');return}
  });
  initialize();
})();
